    24→/**
    25→ * Fast single-pass grayscale + histogram stretch.
    26→ * Converts any paper color to normalized luminance in ~3ms per frame.
    27→ * Does NOT use nested loops — safe for real-time use.
    28→ */
    29→function fastGrayStretch(
    30→  video: HTMLVideoElement,
    31→  canvas: HTMLCanvasElement,
    32→  ctx: CanvasRenderingContext2D,
    33→) {
    34→  const W = video.videoWidth  || 640;
    35→  const H = video.videoHeight || 480;
    36→  canvas.width  = W;
    37→  canvas.height = H;
    38→  ctx.drawImage(video, 0, 0, W, H);
    39→
    40→  const img = ctx.getImageData(0, 0, W, H);
    41→  const d   = img.data;
    42→  const len = d.length;
    43→
    44→  // Pass 1: grayscale + find min/max (single pass, O(n))
    45→  const gray = new Uint8ClampedArray(len >> 2);
    46→  let lo = 255, hi = 0;
    47→  for (let i = 0, p = 0; i < len; i += 4, p++) {
    48→    const g = (77 * d[i] + 150 * d[i + 1] + 29 * d[i + 2]) >> 8;
    49→    gray[p] = g;
    50→    if (g < lo) lo = g;
    51→    if (g > hi) hi = g;
    52→  }
    53→
    54→  // Pass 2: stretch to 0–255 and write back (O(n))
    55→  const range = hi - lo || 1;
    56→  for (let i = 0, p = 0; i < len; i += 4, p++) {
    57→    const v = ((gray[p] - lo) * 255 / range) | 0;
    58→    d[i] = d[i + 1] = d[i + 2] = v;
    59→    d[i + 3] = 255;
    60→  }
    61→  ctx.putImageData(img, 0, 0);
    62→}
