   127→      }
   128→      if (cancelled) return;
   129→      setReady(true);
   130→
   131→      // ── prepare canvas ────────────────────────────────────────────────
   132→      const canvas = canvasRef.current!;
   133→      const ctx    = canvas.getContext("2d", { willReadFrequently: true })!;
   134→
   135→      // ── decoders ──────────────────────────────────────────────────────
   136→      const hints = new Map();
   137→      hints.set(DecodeHintType.POSSIBLE_FORMATS, [
   138→        BarcodeFormat.CODE_128, BarcodeFormat.CODE_39, BarcodeFormat.CODE_93,
   139→        BarcodeFormat.EAN_13,   BarcodeFormat.EAN_8,   BarcodeFormat.UPC_A,
   140→        BarcodeFormat.UPC_E,    BarcodeFormat.ITF,     BarcodeFormat.CODABAR,
   141→      ]);
   142→      hints.set(DecodeHintType.TRY_HARDER, true);
   143→      const zxing = new BrowserMultiFormatReader(hints);
   144→
   145→      let nativeDetector: InstanceType<typeof BarcodeDetector> | null = null;
   146→      if (typeof BarcodeDetector !== "undefined") {
