   166→        if (!code && nativeDetector) {
   167→          try {
   168→            const hits = await nativeDetector.detect(video);
   169→            if (hits.length) code = hits[0].rawValue;
   170→          } catch { /* miss */ }
   171→        }
   172→
   173→        // Pass B: ZXing on raw canvas (works great for white paper, good with TRY_HARDER)
   174→        if (!code) {
   175→          try {
   176→            canvas.width = video.videoWidth;
   177→            canvas.height = video.videoHeight;
   178→            ctx.drawImage(video, 0, 0);
