   252→                <div className="absolute right-0 bg-black/60" style={{ top: "15%", bottom: "15%", width: "5%" }} />
   253→
   254→                <div className="absolute border-2 border-yellow-400"
   255→                     style={{ top: "15%", bottom: "15%", left: "5%", right: "5%" }}>
