import { useEffect, useRef, useCallback, useState } from "react";
import { getSession, saveSession, getSessionTimeoutSettings } from "@/lib/store";

const ACTIVITY_EVENTS = ["mousemove", "mousedown", "keydown", "touchstart", "scroll", "click"];
const WARNING_SECONDS = 60;

export function useSessionTimeout(onLogout: () => void) {
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const warningTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [showWarning, setShowWarning] = useState(false);
  const [secondsLeft, setSecondsLeft] = useState(WARNING_SECONDS);
  const countdownRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const stopAll = useCallback(() => {
    if (timerRef.current) clearTimeout(timerRef.current);
    if (warningTimerRef.current) clearTimeout(warningTimerRef.current);
    if (countdownRef.current) clearInterval(countdownRef.current);
    timerRef.current = null;
    warningTimerRef.current = null;
    countdownRef.current = null;
  }, []);

  const logout = useCallback(() => {
    stopAll();
    setShowWarning(false);
    saveSession(null);
    onLogout();
  }, [stopAll, onLogout]);

  const startCountdown = useCallback(() => {
    setSecondsLeft(WARNING_SECONDS);
    setShowWarning(true);
    if (countdownRef.current) clearInterval(countdownRef.current);
    countdownRef.current = setInterval(() => {
      setSecondsLeft((s) => {
        if (s <= 1) {
          if (countdownRef.current) clearInterval(countdownRef.current);
          return 0;
        }
        return s - 1;
      });
    }, 1000);
    if (timerRef.current) clearTimeout(timerRef.current);
    timerRef.current = setTimeout(logout, WARNING_SECONDS * 1000);
  }, [logout]);

  const resetTimer = useCallback(() => {
    const session = getSession();
    if (!session) return;

    const { timeoutMinutes } = getSessionTimeoutSettings();
    if (timeoutMinutes === 0) return;

    stopAll();
    setShowWarning(false);

    const warningAt = (timeoutMinutes * 60 - WARNING_SECONDS) * 1000;
    if (warningAt <= 0) {
      timerRef.current = setTimeout(logout, timeoutMinutes * 60 * 1000);
    } else {
      warningTimerRef.current = setTimeout(startCountdown, warningAt);
    }
  }, [stopAll, logout, startCountdown]);

  const stayLoggedIn = useCallback(() => {
    resetTimer();
  }, [resetTimer]);

  useEffect(() => {
    const session = getSession();
    if (!session) return;

    const { timeoutMinutes } = getSessionTimeoutSettings();
    if (timeoutMinutes === 0) return;

    resetTimer();

    const handler = () => {
      if (!showWarning) resetTimer();
    };

    ACTIVITY_EVENTS.forEach((e) => window.addEventListener(e, handler, { passive: true }));
    return () => {
      stopAll();
      ACTIVITY_EVENTS.forEach((e) => window.removeEventListener(e, handler));
    };
  }, []);

  return { showWarning, secondsLeft, stayLoggedIn, logout };
}

import { Dialog, DialogContent, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Clock, LogOut } from "lucide-react";

interface SessionTimeoutModalProps {
  open: boolean;
  secondsLeft: number;
  onStay: () => void;
  onLogout: () => void;
}

export function SessionTimeoutModal({ open, secondsLeft, onStay, onLogout }: SessionTimeoutModalProps) {
  return (
    <Dialog open={open} onOpenChange={() => onStay()}>
      <DialogContent
        className="max-w-sm text-center"
        onInteractOutside={(e) => e.preventDefault()}
      >
        <DialogTitle className="sr-only">Session Expiring</DialogTitle>
        <DialogDescription className="sr-only">Your session is about to expire due to inactivity.</DialogDescription>

        <div className="flex flex-col items-center gap-5 py-2">
          <div className="relative flex items-center justify-center">
            <svg className="w-20 h-20 -rotate-90" viewBox="0 0 56 56">
              <circle cx="28" cy="28" r="24" fill="none" stroke="currentColor" strokeWidth="4"
                className="text-muted/30" />
              <circle
                cx="28" cy="28" r="24" fill="none" stroke="currentColor" strokeWidth="4"
                className="text-primary transition-all duration-1000"
                strokeDasharray={`${2 * Math.PI * 24}`}
                strokeDashoffset={`${2 * Math.PI * 24 * (1 - secondsLeft / 60)}`}
                strokeLinecap="round"
              />
            </svg>
            <Clock className="w-7 h-7 text-primary absolute" />
          </div>

          <div className="flex flex-col gap-1">
            <h2 className="text-xl font-bold text-foreground">Still there?</h2>
            <p className="text-muted-foreground text-sm leading-relaxed">
              You'll be logged out in{" "}
              <span className="font-bold text-foreground tabular-nums">{secondsLeft}s</span>{" "}
              due to inactivity.
            </p>
          </div>

          <div className="flex gap-3 w-full">
            <Button
              variant="outline"
              className="flex-1 gap-2"
              onClick={onLogout}
            >
              <LogOut className="w-4 h-4" />
              Log out
            </Button>
            <Button
              className="flex-1"
              onClick={onStay}
            >
              Stay logged in
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

