     4→const ACTIVITY_EVENTS = ["mousemove", "mousedown", "keydown", "touchstart", "scroll", "click"];
     5→const WARNING_SECONDS = 60;
     6→
     7→export function useSessionTimeout(onLogout: () => void) {
     8→  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
     9→  const warningTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    10→  const [showWarning, setShowWarning] = useState(false);
    11→  const [secondsLeft, setSecondsLeft] = useState(WARNING_SECONDS);
    12→  const countdownRef = useRef<ReturnType<typeof setInterval> | null>(null);
    13→
    14→  const stopAll = useCallback(() => {
    15→    if (timerRef.current) clearTimeout(timerRef.current);
    16→    if (warningTimerRef.current) clearTimeout(warningTimerRef.current);
    17→    if (countdownRef.current) clearInterval(countdownRef.current);
    18→    timerRef.current = null;
    19→    warningTimerRef.current = null;
    20→    countdownRef.current = null;
    21→  }, []);
    22→
    23→  const logout = useCallback(() => {
    24→    stopAll();
    25→    setShowWarning(false);
    26→    saveSession(null);
    27→    onLogout();
    28→  }, [stopAll, onLogout]);
    29→
    30→  const startCountdown = useCallback(() => {
    31→    setSecondsLeft(WARNING_SECONDS);
    32→    setShowWarning(true);
    33→    if (countdownRef.current) clearInterval(countdownRef.current);
    34→    countdownRef.current = setInterval(() => {
    35→      setSecondsLeft((s) => {
    36→        if (s <= 1) {
    37→          if (countdownRef.current) clearInterval(countdownRef.current);
    38→          return 0;
    39→        }
    40→        return s - 1;
    41→      });
    42→    }, 1000);
    43→    if (timerRef.current) clearTimeout(timerRef.current);
    44→    timerRef.current = setTimeout(logout, WARNING_SECONDS * 1000);
    45→  }, [logout]);
    46→
    47→  const resetTimer = useCallback(() => {
    48→    const session = getSession();
    49→    if (!session) return;
    50→
    51→    const { timeoutMinutes } = getSessionTimeoutSettings();
    52→    if (timeoutMinutes === 0) return;
    53→
    54→    stopAll();
    55→    setShowWarning(false);
    56→
    57→    const warningAt = (timeoutMinutes * 60 - WARNING_SECONDS) * 1000;
    58→    if (warningAt <= 0) {
    59→      timerRef.current = setTimeout(logout, timeoutMinutes * 60 * 1000);
    60→    } else {
    61→      warningTimerRef.current = setTimeout(startCountdown, warningAt);
    62→    }
    63→  }, [stopAll, logout, startCountdown]);
    64→
    65→  const stayLoggedIn = useCallback(() => {
    66→    resetTimer();
    67→  }, [resetTimer]);
    68→
    69→  useEffect(() => {
    70→    const session = getSession();
    71→    if (!session) return;
    72→
    73→    const { timeoutMinutes } = getSessionTimeoutSettings();
    74→    if (timeoutMinutes === 0) return;
    75→
    76→    resetTimer();
    77→
    78→    const handler = () => {
    79→      if (!showWarning) resetTimer();
    80→    };
    81→
    82→    ACTIVITY_EVENTS.forEach((e) => window.addEventListener(e, handler, { passive: true }));
    83→    return () => {
    84→      stopAll();
    85→      ACTIVITY_EVENTS.forEach((e) => window.removeEventListener(e, handler));
    86→    };
    87→  }, []);
    88→
    89→  return { showWarning, secondsLeft, stayLoggedIn, logout };
    90→}
