import { useEffect, useRef, useState, useCallback } from "react";
import { getScannerSettings } from "@/lib/store";
import {
  BrowserMultiFormatReader,
  BarcodeFormat,
  DecodeHintType,
} from "@zxing/library";
import { Dialog, DialogContent, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { X, CameraOff, Zap } from "lucide-react";

declare class BarcodeDetector {
  constructor(options?: { formats?: string[] });
  detect(source: HTMLVideoElement | HTMLCanvasElement): Promise<Array<{ rawValue: string }>>;
  static getSupportedFormats(): Promise<string[]>;
}

interface ScannerModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onDecode: (text: string) => void;
}

// ─────────────────────────────────────────────────────────────────────────────
// Image helpers
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Draw the full video frame onto canvas (native resolution).
 */
function drawFull(
  video: HTMLVideoElement,
  canvas: HTMLCanvasElement,
  ctx: CanvasRenderingContext2D,
) {
  const W = video.videoWidth  || 640;
  const H = video.videoHeight || 480;
  canvas.width  = W;
  canvas.height = H;
  ctx.drawImage(video, 0, 0, W, H);
}

/**
 * Crop a horizontal band (default: center 30% of height) and scale it UP.
 * This is the key fix for long barcodes — bars become wider relative to
 * ZXing's minimum reliable bar width (~2 px).
 *
 * stripFrac  — fraction of frame height to crop (0.30 = 30%)
 * scale      — how much to enlarge (2.0 = 2× upscale)
 * yFrac      — vertical center of the strip (0.5 = middle of frame)
 */
function drawStrip(
  video: HTMLVideoElement,
  canvas: HTMLCanvasElement,
  ctx: CanvasRenderingContext2D,
  stripFrac = 0.30,
  scale     = 2.0,
  yFrac     = 0.5,
) {
  const W  = video.videoWidth  || 640;
  const H  = video.videoHeight || 480;
  const sh = Math.max(1, Math.round(H * stripFrac));
  const sy = Math.max(0, Math.min(H - sh, Math.round(H * yFrac - sh / 2)));
  canvas.width  = Math.round(W * scale);
  canvas.height = Math.round(sh * scale);
  ctx.drawImage(video, 0, sy, W, sh, 0, 0, canvas.width, canvas.height);
}

/**
 * Grayscale + histogram stretch — normalises luminance for coloured paper.
 * Operates in-place on whatever is already drawn on the canvas.
 */
function grayStretch(canvas: HTMLCanvasElement, ctx: CanvasRenderingContext2D) {
  const img = ctx.getImageData(0, 0, canvas.width, canvas.height);
  const d   = img.data;
  const len = d.length;
  const gray = new Uint8ClampedArray(len >> 2);
  let lo = 255, hi = 0;
  for (let i = 0, p = 0; i < len; i += 4, p++) {
    const g = (77 * d[i] + 150 * d[i + 1] + 29 * d[i + 2]) >> 8;
    gray[p] = g;
    if (g < lo) lo = g;
    if (g > hi) hi = g;
  }
  const range = hi - lo || 1;
  for (let i = 0, p = 0; i < len; i += 4, p++) {
    const v = ((gray[p] - lo) * 255 / range) | 0;
    d[i] = d[i + 1] = d[i + 2] = v;
    d[i + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
}

// ─────────────────────────────────────────────────────────────────────────────
// Component
// ─────────────────────────────────────────────────────────────────────────────

export function ScannerModal({ open, onOpenChange, onDecode }: ScannerModalProps) {
  const videoRef    = useRef<HTMLVideoElement>(null);
  const canvasRef   = useRef<HTMLCanvasElement>(null);
  const streamRef   = useRef<MediaStream | null>(null);
  const timerRef    = useRef<ReturnType<typeof setTimeout> | null>(null);
  const activeRef   = useRef(false);
  const lastCodeRef = useRef<string | null>(null);

  const [error, setError]       = useState("");
  const [ready, setReady]       = useState(false);
  const [torch, setTorch]       = useState(false);
  const [hasTorch, setHasTorch] = useState(false);

  const stopAll = useCallback(() => {
    activeRef.current = false;
    if (timerRef.current) { clearTimeout(timerRef.current); timerRef.current = null; }
    streamRef.current?.getTracks().forEach((t) => t.stop());
    streamRef.current = null;
    if (videoRef.current) videoRef.current.srcObject = null;
    lastCodeRef.current = null;
    setReady(false); setTorch(false); setHasTorch(false);
  }, []);

  const applyTorch = useCallback(async (on: boolean) => {
    const track = streamRef.current?.getVideoTracks()[0];
    if (!track) return;
    try { await (track as any).applyConstraints({ advanced: [{ torch: on }] }); setTorch(on); }
    catch { /* not supported */ }
  }, []);

  useEffect(() => {
    if (!open) { stopAll(); setError(""); return; }

    let cancelled = false;
    activeRef.current = true;

    async function run() {
      setError(""); setReady(false);

      // ── open camera at the highest available resolution ────────────────
      let stream: MediaStream;
      try {
        stream = await navigator.mediaDevices.getUserMedia({
          audio: false,
          video: {
            facingMode: { ideal: "environment" },
            // Request full HD — gives 3× more pixels per bar vs 720p
            width:  { ideal: 1920, min: 640 },
            height: { ideal: 1080, min: 480 },
          },
        });
      } catch {
        if (!cancelled) setError("Camera access denied — allow camera permission and reload.");
        return;
      }
      if (cancelled) { stream.getTracks().forEach((t) => t.stop()); return; }

      streamRef.current = stream;
      const track = stream.getVideoTracks()[0];
      const caps  = (track.getCapabilities?.() ?? {}) as any;

      // Enable torch if requested
      if (caps.torch) { setHasTorch(true); if (getScannerSettings().autoTorch) applyTorch(true); }

      // Request continuous autofocus — critical for sharp long-barcode reads
      try {
        if (caps.focusMode?.includes?.("continuous")) {
          await (track as any).applyConstraints({ advanced: [{ focusMode: "continuous" }] });
        }
      } catch { /* unsupported */ }

      const video = videoRef.current!;
      video.srcObject = stream;
      video.setAttribute("playsinline", "true");
      video.muted = true;
      try { await video.play(); } catch {
        if (!cancelled) setError("Video playback failed."); return;
      }
      if (cancelled) return;
      setReady(true);

      // ── prepare canvas ─────────────────────────────────────────────────
      const canvas = canvasRef.current!;
      const ctx    = canvas.getContext("2d", { willReadFrequently: true })!;

      // ── ZXing — configured for long linear barcodes ───────────────────
      const hints = new Map();
      hints.set(DecodeHintType.POSSIBLE_FORMATS, [
        BarcodeFormat.CODE_128, BarcodeFormat.CODE_39, BarcodeFormat.CODE_93,
        BarcodeFormat.EAN_13,   BarcodeFormat.EAN_8,   BarcodeFormat.UPC_A,
        BarcodeFormat.UPC_E,    BarcodeFormat.ITF,     BarcodeFormat.CODABAR,
      ]);
      hints.set(DecodeHintType.TRY_HARDER, true);
      // Allow ZXing to also try inverted barcodes (white bars on black)
      hints.set(DecodeHintType.ALSO_INVERTED, true);
      const zxing = new BrowserMultiFormatReader(hints);

      // ── native BarcodeDetector ─────────────────────────────────────────
      let nativeDetector: InstanceType<typeof BarcodeDetector> | null = null;
      if (typeof BarcodeDetector !== "undefined") {
        try {
          const fmts = await BarcodeDetector.getSupportedFormats();
          nativeDetector = new BarcodeDetector({ formats: fmts });
        } catch { /* unavailable */ }
      }

      // ── scan loop ──────────────────────────────────────────────────────
      const scan = async () => {
        if (!activeRef.current || cancelled) return;

        if (video.readyState < 2 || !video.videoWidth) {
          timerRef.current = setTimeout(scan, 100); return;
        }

        let code: string | null = null;

        // ── Pass 1: Native detector on live <video> (uses hardware decoder) ──
        if (!code && nativeDetector) {
          try {
            const hits = await nativeDetector.detect(video);
            if (hits.length) code = hits[0].rawValue;
          } catch { /* miss */ }
        }

        // ── Pass 2: ZXing on full native-resolution frame ─────────────────
        // Catches any barcode that fits within the full frame at 1080p
        if (!code) {
          try {
            drawFull(video, canvas, ctx);
            code = zxing.decodeFromCanvas(canvas).getText();
          } catch { /* miss */ }
        }

        // ── Pass 3: ZXing on 2× upscaled center horizontal strip ──────────
        // KEY FIX FOR LONG BARCODES: crops the center 30% of frame height
        // and doubles it — bar width goes from ~2px to ~4px, well above
        // ZXing's minimum threshold.
        if (!code) {
          try {
            drawStrip(video, canvas, ctx, 0.30, 2.0, 0.5);
            code = zxing.decodeFromCanvas(canvas).getText();
          } catch { /* miss */ }
        }

        // ── Pass 4: ZXing on 2× upscaled strip — upper third ─────────────
        // Catches barcodes held slightly above center
        if (!code) {
          try {
            drawStrip(video, canvas, ctx, 0.30, 2.0, 0.33);
            code = zxing.decodeFromCanvas(canvas).getText();
          } catch { /* miss */ }
        }

        // ── Pass 5: ZXing on 2× upscaled strip — lower third ─────────────
        if (!code) {
          try {
            drawStrip(video, canvas, ctx, 0.30, 2.0, 0.67);
            code = zxing.decodeFromCanvas(canvas).getText();
          } catch { /* miss */ }
        }

        // ── Pass 6: ZXing on grayscale-stretched full frame ───────────────
        // Helps coloured paper (green, yellow, etc.)
        if (!code) {
          try {
            drawFull(video, canvas, ctx);
            grayStretch(canvas, ctx);
            code = zxing.decodeFromCanvas(canvas).getText();
          } catch { /* miss */ }
        }

        // ── Pass 7: ZXing on grayscale-stretched + 2× upscaled strip ─────
        // Long barcode + coloured paper — the hardest case
        if (!code) {
          try {
            drawStrip(video, canvas, ctx, 0.30, 2.0, 0.5);
            grayStretch(canvas, ctx);
            code = zxing.decodeFromCanvas(canvas).getText();
          } catch { /* miss */ }
        }

        // ── Pass 8: Native detector on grayscale-stretched full frame ─────
        if (!code && nativeDetector) {
          try {
            drawFull(video, canvas, ctx);
            grayStretch(canvas, ctx);
            const hits = await nativeDetector.detect(canvas);
            if (hits.length) code = hits[0].rawValue;
          } catch { /* miss */ }
        }

        // ── Confirm: require two consecutive identical reads ───────────────
        if (code) {
          if (lastCodeRef.current === code) {
            onDecode(code);
            onOpenChange(false);
            return;
          }
          lastCodeRef.current = code;
        } else {
          lastCodeRef.current = null;
        }

        if (activeRef.current && !cancelled)
          timerRef.current = setTimeout(scan, 120);
      };

      scan();
    }

    run().catch(() => { if (!cancelled) setError("Camera error — reload and try again."); });
    return () => { cancelled = true; stopAll(); };
  }, [open, onDecode, onOpenChange, stopAll, applyTorch]);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        className="max-w-full w-full sm:max-w-3xl p-0 overflow-hidden bg-black border-none"
        aria-describedby="scanner-description"
      >
        <DialogTitle className="sr-only">Barcode Scanner</DialogTitle>
        <DialogDescription id="scanner-description" className="sr-only">Scan a barcode using the camera.</DialogDescription>

        <div className="relative w-full bg-black" style={{ aspectRatio: "16/9" }}>
          {error ? (
            <div className="absolute inset-0 text-white flex flex-col items-center justify-center gap-4 p-6">
              <CameraOff className="w-14 h-14 text-red-400" />
              <p className="text-base text-center">{error}</p>
            </div>
          ) : (
            <>
              <video ref={videoRef} className="absolute inset-0 w-full h-full object-cover" playsInline muted autoPlay />
              <canvas ref={canvasRef} className="hidden" />
            </>
          )}

          {!error && (
            <>
              {/* ── Scan zone overlay ── */}
              {/* Wide, flat horizontal strip — matches the 3-strip scan logic above */}
              <div className="absolute inset-0 pointer-events-none z-10">
                {/* Top + bottom dimming */}
                <div className="absolute top-0 left-0 right-0 bg-black/60" style={{ height: "25%" }} />
                <div className="absolute bottom-0 left-0 right-0 bg-black/60" style={{ height: "25%" }} />
                {/* Thin left/right dimming — nearly edge-to-edge for long barcodes */}
                <div className="absolute left-0 bg-black/60" style={{ top: "25%", bottom: "25%", width: "1.5%" }} />
                <div className="absolute right-0 bg-black/60" style={{ top: "25%", bottom: "25%", width: "1.5%" }} />

                {/* Bright scan-zone border */}
                <div
                  className="absolute border-2 border-yellow-400"
                  style={{ top: "25%", bottom: "25%", left: "1.5%", right: "1.5%" }}
                >
                  {/* Corner markers */}
                  <span className="absolute top-0    left-0  w-6 h-6 border-t-4 border-l-4 border-yellow-400" />
                  <span className="absolute top-0    right-0 w-6 h-6 border-t-4 border-r-4 border-yellow-400" />
                  <span className="absolute bottom-0 left-0  w-6 h-6 border-b-4 border-l-4 border-yellow-400" />
                  <span className="absolute bottom-0 right-0 w-6 h-6 border-b-4 border-r-4 border-yellow-400" />
                  {/* Animated scan line */}
                  <div className="absolute top-1/2 left-0 w-full h-[2px] -translate-y-1/2 bg-red-500 shadow-[0_0_10px_4px_rgba(239,68,68,0.6)]" />
                </div>
              </div>

              {/* ── Hint text ── */}
              <div className="absolute bottom-3 left-0 right-0 z-20 text-center pointer-events-none flex flex-col items-center gap-1">
                <p className="bg-black/65 text-white px-4 py-1.5 inline-block rounded-full text-sm">
                  {ready ? "Align barcode within the frame" : "Starting camera…"}
                </p>
                {ready && (
                  <p className="bg-black/50 text-yellow-300 px-3 py-1 inline-block rounded-full text-xs">
                    Long barcode? Move further back so the full barcode fits inside
                  </p>
                )}
              </div>
            </>
          )}

          {/* ── Controls ── */}
          <div className="absolute top-3 right-3 z-20 flex gap-2">
            {hasTorch && (
              <Button variant="secondary" size="icon"
                className={`rounded-full border-none ${torch ? "bg-yellow-400 text-black" : "bg-black/50 text-white hover:bg-black/70"}`}
                onClick={() => applyTorch(!torch)}>
                <Zap className="w-5 h-5" />
              </Button>
            )}
            <Button variant="secondary" size="icon"
              className="rounded-full bg-black/50 text-white hover:bg-black/70 border-none"
              onClick={() => onOpenChange(false)}>
              <X className="w-5 h-5" />
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

